from approved_route8_drowzee_changes import restore_route8_text

def restore_kanto_central_text(path,source):
    if str(path)!="src/data/wild_encounters.json":return source
    # Reconcile the later assistant-delegated Drowzee correction before
    # reverting the original Kanto-central ecology batch and frozen hashes.
    source=restore_route8_text(path,source)
    for label,original in ORIGINAL_KANTO_CENTRAL.items():
        marker='"base_label": "'+label+'"' 
        i=source.index('"mons": [',source.index(marker))
        current=BALANCED_KANTO_CENTRAL[label]
        assert source[i:i+len(current)]==current,label
        source=source[:i]+original+source[i+len(current):]
    return source

def prior_kanto_central_source(path):
    return restore_kanto_central_text(path,prior_bulk_grass_source(path).decode("utf-8")).encode("utf-8")

def restore_prior_kanto_central_text(path,source):
    return restore_kanto_central_text(path,restore_prior_bulk_grass_text(path,source))
